package tv.iptvibe.mobile;
import java.net.*;import java.io.*;import org.json.JSONObject;
final class AccountApi {
 static final String ORIGIN="https://iptvibe.pages.dev";
 static final class Failure extends Exception {final int status;final String code;Failure(int status,String code){super(code);this.status=status;this.code=code;}}
 static JSONObject call(String path,JSONObject body)throws Exception{String cookie=AccountStore.token().isEmpty()?null:"iptvibe_session="+AccountStore.token();HttpURLConnection c=(HttpURLConnection)new URL(ORIGIN+"/api/account"+path).openConnection();c.setInstanceFollowRedirects(false);c.setConnectTimeout(12000);c.setReadTimeout(15000);c.setRequestMethod(body==null?"GET":"POST");c.setRequestProperty("Origin",ORIGIN);c.setRequestProperty("Content-Type","application/json");if(cookie!=null)c.setRequestProperty("Cookie",cookie);try{if(body!=null){c.setDoOutput(true);try(OutputStream out=c.getOutputStream()){out.write(body.toString().getBytes("UTF-8"));}}int status=c.getResponseCode();InputStream stream=status<400?c.getInputStream():c.getErrorStream();if(stream==null)throw new Failure(status,"SERVICE_UNAVAILABLE");String data;try(InputStream in=stream;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>2*1024*1024)throw new IOException();out.write(b,0,n);}data=out.toString("UTF-8");}JSONObject result=new JSONObject(data);if(status<400&&path.equals("/login")){String header=c.getHeaderField("Set-Cookie");java.util.regex.Matcher match=java.util.regex.Pattern.compile("iptvibe_session=([A-Za-z0-9_-]{43})").matcher(header==null?"":header);if(!match.find())throw new Failure(503,"SERVICE_UNAVAILABLE");AccountStore.save(match.group(1));}if(status<400&&path.equals("/logout"))AccountStore.clear();if(status>=400)throw new Failure(status,result.optString("code","SERVICE_UNAVAILABLE"));return result;}finally{c.disconnect();}}
}
